// One teardown row per ad. Transcribed video ads first, longest first; image/text ads at the bottom.
const rows = $input.all().map(({ json: ad }) => {
  const transcript = ad.transcript || '';
  const words = transcript.trim() ? transcript.trim().split(/\s+/).length : 0;
  return {
    advertiser: ad.advertiser || '',
    headline: ad.headline || '',
    ad_id: ad.adId || '',
    format: ad.format || '',
    status: ad.status || '',
    hook_first_3s: ad.hook3s || '',
    seconds: ad.durationSeconds ?? null,
    transcript_words: words,
    language: ad.language || '',
    charged: ad.charged === true,
    transcript,
    ad_text: ad.adText || '',
    paying_entity: ad.payingEntity || '',
    impressions: ad.impressions || '',
    availability: ad.availability || '',
    detail_url: ad.detailUrl || '',
    note: ad.statusReason || '',
  };
});

rows.sort((a, b) => (b.status === 'transcribed') - (a.status === 'transcribed') || (b.seconds || 0) - (a.seconds || 0));

return rows.map((row) => ({ json: row }));
